context.storyboard:
{
  "$schema": "../storyboard.schema.json",
  "id": "recruitment-workflows",
  "feature_name": "Recruitment workflows",
  "source_faq_url": "https://support.vomevolunteer.com/portal/en/kb/articles/recruitment-workflows-on-vome",
  "one_thing": "You should not have to send every volunteer through the same long application form.",

  "voice": {
    "name": "Maya",
    "model": "eleven_v4",
    "settings": { "stability": 0.5, "similarity_boost": 0.75, "speed": 1.0 }
  },
  "music": "audio/music/Bright_Focus.wav",
  "pacing": { "gap": 0.5, "lead_in": 0.3, "tail": 3.5 },

  "scenes": [
    {
      "id": "hook",
      "template": "hook",
      "lines": [
        {
          "vo": "[calm, measured] Still sending every volunteer through the same application form?",
          "captions": []
        }
      ],
      "on_screen": {
        "lines": [
          "Still sending",
          "*every volunteer*",
          "through the same",
          "application form?"
        ]
      }
    },

    {
      "id": "problem",
      "template": "problem",
      "lines": [
        {
          "vo": "A 13 year old may need parental consent.",
          "captions": ["A *13 year old* may need parental consent."],
          "cue": "form_in"
        },
        {
          "vo": "Whereas a returning volunteer does not need to reapply.",
          "captions": ["Whereas a *returning volunteer*", "does not need to reapply."],
          "cue": "badge_in"
        },
        {
          "vo": "But everyone is still getting the same long form.",
          "captions": ["But *everyone* is still getting", "the same long form."],
          "cue": "tags_in"
        }
      ],
      "on_screen": {
        "chip": "Application",
        "title": "General Application Form",
        "badge": "42 questions",
        "fields": [
          { "label": "Full name" },
          { "label": "Date of birth" },
          { "label": "Emergency contact" },
          { "label": "Driver's licence number", "tag": "Not relevant" },
          { "label": "Vehicle insurance provider", "tag": "Not relevant" },
          { "label": "Previous volunteer experience" },
          { "label": "Parent or guardian signature", "tag": "Not relevant" },
          { "label": "T-shirt size" },
          { "label": "Dietary restrictions" }
        ]
      }
    },

    {
      "id": "ui_demo",
      "template": "ui_demo",
      "lines": [
        {
          "vo": "Vome lets you build recruitment workflows based on your path.",
          "stack": true,
          "captions": ["*Vome* lets you build", "recruitment workflows", "based on your path."],
          "cue": "card_in"
        },
        {
          "vo": "[curious] Under eighteen? Send them to the minor application.",
          "captions": ["Under 18?", "Send them to the minor application."],
          "cue": "rule1"
        },
        {
          "vo": "[curious] Already approved elsewhere? Register them instantly.",
          "captions": ["Already approved elsewhere?", "Register them instantly."],
          "cue": "rule2"
        },
        {
          "vo": "Everyone else gets the general form.",
          "captions": ["Everyone else gets the general form."],
          "cue": "rule3"
        },
        {
          "vo": "Rules run top to bottom, and the first match wins.",
          "captions": ["Rules run top to bottom,", "and the first match wins."],
          "cue": "match"
        }
      ],
      "on_screen": {
        "chip": "Recruitment",
        "title": "Food Bank Driver",
        "status": "On",
        "label": "Dynamic workflow",
        "applicant": { "initials": "PO", "name": "Priya O., 16" },
        "rules": [
          {
            "condition": "Age under 18",
            "action": "Submit a Vome form",
            "action_kind": "form",
            "meta": "Minor Application Form"
          },
          {
            "condition": "Approved in same category",
            "action": "Auto-approve opportunity",
            "action_kind": "auto"
          },
          {
            "condition": "Everyone (catch-all)",
            "action": "Submit a Vome form",
            "action_kind": "form",
            "meta": "General Application Form"
          }
        ]
      }
    },

    {
      "id": "benefit",
      "template": "benefit",
      "gap_before": 1.2,
      "lines": [
        {
          "vo": "[warm] Every volunteer gets the shortest path.",
          "captions": [],
          "cue": "benefit_in"
        }
      ],
      "on_screen": {
        "lines": ["Every volunteer gets", "*the shortest path.*"],
        "routes": ["Under 18", "Returning", "Everyone else"]
      }
    },

    {
      "id": "cta",
      "template": "cta",
      "gap_before": 2.5,
      "lines": [
        {
          "vo": "[confident] Build yours in Vome. [warm] Build your first form free.",
          "stack": true,
          "captions": ["Build yours in Vome.", "*Build your first form free.*"],
          "cue": "cta_in"
        }
      ],
      "on_screen": {
        "tagline": [
          "The volunteer management software",
          "*your volunteers and staff*",
          "actually want to use"
        ],
        "url": "vomevolunteer.com"
      }
    }
  ]
}

context.positioning:
{
  "audience": "Volunteer coordinators who review every application by hand",
  "whats_new": "Recruitment workflows: IF-THEN rules decide what happens when someone applies",
  "single_claim": "Vome sends each volunteer down the right application path automatically.",
  "must_not_say": [
    "instantly",
    "no more forms",
    "free"
  ]
}

